; =====================================================================
;  DISPLAY.ASM -- display list, DLI, VBI and map drawing
;
;  Screen layout (192 scan lines, D12):
;    24 blank lines
;     2 x ANTIC mode 2  status bar  (ROM font, OS shadow colours)
;    11 x ANTIC mode 5  map         (map font, colours set by DLI)
;
;  One map square = one tile = 2 mode 5 characters = 8 x 8 pixels,
;  8 colour clocks wide and 16 scan lines tall; 20 x 11 squares.
;  Tiles, font and island data come from TILES.ASM / FONT_MAP.ASM /
;  ISLANDS.ASM, generated by tools/mkfont.py.
;
;  The DLI on the last status line sets the map colours and row 0's
;  font; a DLI at the end of each map row 0-9 then sets the next row's
;  font from ROWFONT (coast tiles are spread over up to N_FONTS fonts,
;  fixed tiles have the same codes in all of them).  The deferred VBI
;  points VDSLST back at DLI_MAP for the next frame; the OS VBI
;  restores the status-bar values from the shadow registers.
; =====================================================================

MAPROWS =  11           ; mode 5 lines (square rows) in the map zone
MAPSQ   =  20           ; squares per row
MAPCOLS =  40           ; characters per line, normal playfield width
HP_MAP  =  48           ; horizontal position of map column 0 (P/M)
PM_MAP  =  24           ; double-line P/M line of map row 0 (scan line 48)

; Status bar colours (OS shadows)
C_SBAR  =  $82          ; status bar background (COLPF2)
C_STXT  =  $0E          ; status bar text luminance (COLPF1)
C_SBRD  =  $00          ; status bar border (COLBK)

; Map palette (D16), set by the DLI
C_SEA   =  $84          ; COLBK  -- sea
C_GRASS =  $C6          ; COLPF0 -- grass
C_DARK  =  $00          ; COLPF1 -- black: fort, factory, crop, rebel, boats
C_LIGHT =  $1C          ; COLPF2 -- yellow: beach, house roof, smoke, sail
C_WHITE =  $0E          ; COLPF3 -- white (inverse chars): school, hospital

; ---------------------------------------------------------------------
;  DISP_INIT -- install display list, DLI and VBI.
;  Writes only RAM vectors and shadows; calls no OS routines.
; ---------------------------------------------------------------------
DISP_INIT
        LDA #0
        STA NMIEN       ; no VBI/DLI while vectors are patched
        STA SDMCTL
        STA DMACTL

        LDX #STATLEN-1  ; status lines from template
DI_STAT LDA STATTPL,X
        STA STATUS1,X
        DEX
        BPL DI_STAT

        JSR MAP_ROWS
        JSR MAP_DRAW
        JSR PM_INIT
        JSR PAL_NORM

        LDA #<DLI_MAP
        STA VDSLST
        LDA #>DLI_MAP
        STA VDSLST+1

        LDA VVBLKD      ; chain to whatever deferred VBI was there
        STA OLDVBD
        LDA VVBLKD+1
        STA OLDVBD+1
        LDA #<VBI_D
        STA VVBLKD
        LDA #>VBI_D
        STA VVBLKD+1

        LDA #<DLIST
        STA SDLSTL
        LDA #>DLIST
        STA SDLSTH

        LDA #C_SBAR
        STA COLOR2
        LDA #C_STXT
        STA COLOR1
        LDA #C_SBRD
        STA COLOR4
        LDA #ROMFONT
        STA CHBAS

        LDA #DMA_NORM+DMA_PM
        STA SDMCTL
        LDA #NMI_VBI+NMI_DLI
        STA NMIEN
        RTS

; ---------------------------------------------------------------------
;  DLI_MAP -- switch font and colours for the map zone
; ---------------------------------------------------------------------
DLI_MAP
        PHA
        TXA
        PHA
        TYA
        PHA
        LDA MAPPAL      ; map palette from RAM (PAL_NORM / PAL_DIM)
        LDX MAPPAL+1
        LDY MAPPAL+2
        STA WSYNC
        STA COLBK
        STX COLPF0
        STY COLPF1
        LDA MAPPAL+3
        STA COLPF2
        LDA MAPPAL+4
        STA COLPF3
        LDA HELPON
        BNE DM_HELP
        LDA ROWFONT     ; font for map row 0
        STA CHBASE
        LDA HP3ROW      ; player 3 (fish) position for row 0
        STA HPOSP3
        LDA HP2ROW      ; player 2 (weather) position and colour
        STA HPOSP2
        LDA WCROW
        STA COLPM2
        LDA HMROW       ; missiles (pirates) position for row 0
        JSR DLI_MSL
DM_ROWS         LDA #1
        STA DLIROW
        LDA #<DLI_ROW   ; the rest of this frame's DLIs are map rows
        STA VDSLST
        LDA #>DLI_ROW
        STA VDSLST+1
        PLA
        TAY
        PLA
        TAX
        PLA
        RTI
DM_HELP LDA #>HLPFONT     ; help screen (HELP.ASM): its font, no fish;
        STA CHBASE      ; HDLIST has no row DLIs
        LDA #0
        STA HPOSP3
        STA HPOSP2      ; no weather either
        JSR DLI_MSL     ; nor pirates
        JMP DM_ROWS

; ---------------------------------------------------------------------
;  PAL_NORM -- map colours to the D16 palette
;  PAL_DIM  -- map colours at half brightness (pause)
;  The DLI copies MAPPAL (sea, grass, dark, light, white) to the
;  colour registers each frame.  Trash A, X.
; ---------------------------------------------------------------------
PAL_NORM
        LDX #4
PN_LOOP LDA PALTAB,X
        STA MAPPAL,X
        DEX
        BPL PN_LOOP
        RTS
PAL_DIM
        LDX #4
PD_LOOP LDA PALTAB,X
        AND #$0F        ; luminance
        LSR A
        AND #$0E
        STA PD_LUM
        LDA PALTAB,X
        AND #$F0        ; hue
        ORA PD_LUM
        STA MAPPAL,X
        DEX
        BPL PD_LOOP
        RTS

PALTAB  .BYTE C_SEA,C_GRASS,C_DARK,C_LIGHT,C_WHITE

; ---------------------------------------------------------------------
;  DLI_ROW -- end of map row n-1: switch to row n's font and set
;  the horizontal positions of player 3 (HP3ROW, FISH.ASM), player 2
;  (HP2ROW, WEATHER.ASM) and the missiles (HMROW, PIRATES.ASM) and
;  player 2's colour for row n
; ---------------------------------------------------------------------
DLI_ROW
        PHA
        TXA
        PHA
        LDX DLIROW
        LDA ROWFONT,X
        STA WSYNC
        STA CHBASE
        LDA HP3ROW,X    ; player 3 (fish) position for row n
        STA HPOSP3
        LDA HP2ROW,X    ; player 2 (weather) position and colour
        STA HPOSP2
        LDA WCROW,X
        STA COLPM2
        LDA HMROW,X     ; missiles (pirates): M3 at HMROW, M2-M0
        STA HPOSM3      ; 2 colour clocks apart each (DLI_MSL, inline
        CLC             ; for time)
        ADC #2
        STA HPOSM2
        ADC #2
        STA HPOSM1
        ADC #2
        STA HPOSM0
        INC DLIROW
        PLA
        TAX
        PLA
        RTI

; DLI_MSL -- missiles side by side as an 8-pixel fifth player: M3 at
; A, M2, M1, M0 2 colour clocks apart each.  (A = 0: all off the left.)
DLI_MSL STA HPOSM3
        CLC
        ADC #2
        STA HPOSM2
        ADC #2
        STA HPOSM1
        ADC #2
        STA HPOSM0
        RTS

; ---------------------------------------------------------------------
;  VBI_D -- deferred VBI: frame counter, sound, keep attract mode off
; ---------------------------------------------------------------------
VBI_D
        INC FRAME
        JSR SND_VBI
        JSR SPR_VBI
        LDA #0          ; players 2 and 3 hidden above the map (the
        STA HPOSP2      ; DLIs set them)
        STA HPOSP3
        JSR DLI_MSL     ; and the missiles
        LDA #0
        STA ATRACT
        LDA #<DLI_MAP   ; first DLI of the next frame
        STA VDSLST
        LDA #>DLI_MAP
        STA VDSLST+1
        JMP (OLDVBD)

; ---------------------------------------------------------------------
;  MAP_ROWS -- build the screen address of each map row
;  Trashes A, X.
; ---------------------------------------------------------------------
MAP_ROWS
        LDA #<MAPSCR
        STA ROWLO
        LDA #>MAPSCR
        STA ROWHI
        LDX #0
MR_NEXT CLC
        LDA ROWLO,X
        ADC #MAPCOLS
        STA ROWLO+1,X
        LDA ROWHI,X
        ADC #0
        STA ROWHI+1,X
        INX
        CPX #MAPROWS-1
        BNE MR_NEXT
        RTS

; ---------------------------------------------------------------------
;  MAP_DRAW -- draw the island terrain (ISLTILE) into screen memory
;  Each tile becomes characters TILECH[t] and TILECH[t]+1.
;  Trashes A, X, Y, ZPTR.
; ---------------------------------------------------------------------
MAP_DRAW
        LDX #0
        STX MROW
        STX GIDX
MD_ROW  LDY MROW
        LDA ROWLO,Y
        STA ZPTR
        LDA ROWHI,Y
        STA ZPTR+1
        LDY #0          ; character column
MD_COL  LDX GIDX
        LDA ISLTILE,X   ; tile number
        TAX
        LDA TILECH,X    ; left character
        STA (ZPTR),Y
        INY
        CLC
        ADC #1          ; right character (bit 7 kept: codes are even)
        STA (ZPTR),Y
        INY
        INC GIDX
        CPY #MAPCOLS
        BNE MD_COL
        INC MROW
        LDA MROW
        CMP #MAPROWS
        BNE MD_ROW
        RTS

; ---------------------------------------------------------------------
;  Status bar template (screen codes), 2 lines of 40.  Copied into the
;  RAM status lines STATUS1/STATUS2 (VARS.ASM) by DISP_INIT.
; ---------------------------------------------------------------------
STATTPL .SBYTE "GOLD       TURNS     TIME      GOLD     "
        .SBYTE "POP                            POP      "
STATLEN =  80

; Offsets of the number fields in STATUS1 (R-SCR-1)
ST_G0   =  5            ; player 1 gold, 4 digits
ST_TRN  =  17           ; rounds left, 2 digits
ST_TIME =  26           ; seconds left in the round, 3 digits
ST_G1   =  36           ; player 2 gold, 4 digits

; Offsets of the population fields in STATUS2 (status offsets, D44)
ST_P0   =  44           ; player 1 population, 5 digits
ST_P1   =  75           ; player 2 population, 5 digits

; ---------------------------------------------------------------------
;  MAP_IDX -- grid index of a square
;  In: X = column (0-19), Y = row (0-10).  Out: A = row*20+column.
;  X and Y kept.
; ---------------------------------------------------------------------
MAP_IDX
        TXA
        CLC
        ADC ROWIDX,Y
        RTS

ROWIDX  .BYTE 0,20,40,60,80,100,120,140,160,180,200

; ---------------------------------------------------------------------
;  MAP_PUT -- draw one tile on the map
;  In: A = tile, X = column (0-19), Y = row (0-10).
;  X kept; trashes A, Y, ZPTR, MTILE.
; ---------------------------------------------------------------------
MAP_PUT
        STA MTILE
        LDA ROWLO,Y
        STA ZPTR
        LDA ROWHI,Y
        STA ZPTR+1
        TXA
        PHA
        ASL A           ; two characters per square
        TAY
        LDX MTILE
        LDA TILECH,X    ; left character
        STA (ZPTR),Y
        INY
        CLC
        ADC #1          ; right character
        STA (ZPTR),Y
        PLA
        TAX
        RTS

; ---------------------------------------------------------------------
;  HPOS_COL -- map column under a normal-width P/M horizontal position
;  In: A = horizontal position.  Out: A = column, C clear; C set if
;  the position is off the map.
; ---------------------------------------------------------------------
HPOS_COL
        SEC
        SBC #HP_MAP
        BCC HC_OFF
        LSR A           ; 8 colour clocks per square
        LSR A
        LSR A
        CMP #MAPSQ      ; C set if column >= 20
        RTS
HC_OFF  SEC
        RTS

; ---------------------------------------------------------------------
;  PMY_ROW -- map row under a double-line P/M vertical line
;  In: A = P/M line.  Out: A = row, C clear; C set if off the map.
; ---------------------------------------------------------------------
PMY_ROW
        SEC
        SBC #PM_MAP
        BCC PR_OFF
        LSR A           ; 8 P/M lines (16 scan lines) per square
        LSR A
        LSR A
        CMP #MAPROWS    ; C set if row >= 11
        RTS
PR_OFF  SEC
        RTS

; Tile-to-character table and island data (generated)
        .INCLUDE "islands.asm"

; Display variables (FRAME, DLIROW, ROWLO/ROWHI, MROW, GIDX, MTILE,
; STATUS1/2) live in VARS.ASM.

; =====================================================================
;  Fixed-address data.  Each block must stay on its own boundary:
;  font 1K aligned, display list inside one 1K page, screen inside 4K.
; =====================================================================

; Map fonts at $3000 and, if needed, $4800+ (generated)
        .INCLUDE "font_map.asm"

; ---------------------------------------------------------------------
;  Map screen memory (MAPROWS x MAPCOLS, RAM, drawn at run time)
; ---------------------------------------------------------------------
MAPSCR  =  $3400

; ---------------------------------------------------------------------
;  Display list
; ---------------------------------------------------------------------
        *= $3800
DLIST
        .BYTE DL_BLANK8,DL_BLANK8,DL_BLANK8
        .BYTE DL_LMS+DL_MODE2
        .WORD STATUS1
        .BYTE DL_DLI+DL_MODE2           ; DLI fires at end of this line
        .BYTE DL_DLI+DL_LMS+DL_MODE5    ; map row 0; each DLI sets
        .WORD MAPSCR                    ; the next row's font
        .BYTE DL_DLI+DL_MODE5,DL_DLI+DL_MODE5,DL_DLI+DL_MODE5
        .BYTE DL_DLI+DL_MODE5,DL_DLI+DL_MODE5,DL_DLI+DL_MODE5
        .BYTE DL_DLI+DL_MODE5,DL_DLI+DL_MODE5,DL_DLI+DL_MODE5
        .BYTE DL_MODE5                  ; row 10
        .BYTE DL_JVB
        .WORD DLIST

; Setup screen (SETUP.ASM): must stay in DLIST's page, since setup
; switches between the two by storing only the low byte of SDLSTL
SUDLIST
        .BYTE DL_BLANK8,DL_BLANK8,DL_BLANK8
        .BYTE DL_LMS+DL_MODE7           ; title, 16 lines
        .WORD SU_SCR
        .BYTE DL_BLANK8
        .BYTE DL_LMS+DL_MODE2           ; 18 text lines (SU_LINES)
        .WORD SU_TXT
        .BYTE DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2
        .BYTE DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2
        .BYTE DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2,DL_MODE2
        .BYTE DL_JVB
        .WORD SUDLIST

; Help screen (HELP.ASM): status bar, then 11 mode 5 lines in the help
; font; same page as DLIST, like SUDLIST
HDLIST
        .BYTE DL_BLANK8,DL_BLANK8,DL_BLANK8
        .BYTE DL_LMS+DL_MODE2
        .WORD STATUS1
        .BYTE DL_DLI+DL_MODE2           ; DLI_MAP: colours, help font
        .BYTE DL_LMS+DL_MODE5
        .WORD HELPSCR
        .BYTE DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5
        .BYTE DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5
        .BYTE DL_JVB
        .WORD HDLIST

; Title screen (TITLE.ASM): the logo in mode D, then two text lines;
; same page as DLIST, like SUDLIST
TDLIST
        .BYTE DL_BLANK8,DL_BLANK8,DL_BLANK8,DL_BLANK8
        .BYTE DL_LMS+DL_MODED           ; logo, LOGO_H lines
        .WORD LOGO
        .BYTE DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED
        .BYTE DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED
        .BYTE DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED
        .BYTE DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED
        .BYTE DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED,DL_MODED
        .BYTE DL_BLANK8,DL_BLANK8
        .BYTE DL_LMS+DL_MODE7           ; REBUILD YOUR WORLD
        .WORD TT_SCR
        .BYTE DL_BLANK8,DL_BLANK8,DL_BLANK8
        .BYTE DL_MODE6                  ; the prompt (TT_SCR+20)
        .BYTE DL_JVB
        .WORD TDLIST
